// Responsive logo component — shows actual uploaded PNG
function PHLogo({ size = 40 }) {
  return (
    <img
      src={`data:image/png;base64,${LOGO_B64}`}
      alt="Priya Haraik"
      style={{ height: size, width: "auto", display: "block", objectFit: "contain" }}
    />
  );
}

export default function App() {
  const [screen, setScreen] = useState("splash");
  const [splashCount, setSplashCount] = useState(3);
  const [activeTab, setActiveTab] = useState("home");
  const [searchQuery, setSearchQuery] = useState("");
  const [searchResults, setSearchResults] = useState([]);
  const [selectedVideo, setSelectedVideo] = useState(null);
  const [watermarkPos, setWatermarkPos] = useState({ top: "10%", left: "10%" });
  const [isPlaying, setIsPlaying] = useState(false);
  const userName = "Priya Haraik";
  const userInitials = "PH";
  const userEmail = "priya@gmail.com";

  useEffect(() => {
    if (screen !== "splash") return;
    const timer = setInterval(() => {
      setSplashCount(prev => {
        if (prev <= 1) { clearInterval(timer); setTimeout(() => setScreen("home"), 400); return 0; }
        return prev - 1;
      });
    }, 700);
    return () => clearInterval(timer);
  }, [screen]);

  useEffect(() => {
    if (!isPlaying) return;
    const positions = [
      { top: "8%", left: "5%" }, { top: "8%", left: "55%" },
      { top: "45%", left: "5%" }, { top: "45%", left: "55%" },
      { top: "80%", left: "5%" }, { top: "80%", left: "55%" },
    ];
    let i = 0;
    const interval = setInterval(() => { i = (i + 1) % positions.length; setWatermarkPos(positions[i]); }, 3000);
    return () => clearInterval(interval);
  }, [isPlaying]);

  useEffect(() => {
    if (searchQuery.trim().length < 2) { setSearchResults([]); return; }
    const q = searchQuery.toLowerCase();
    setSearchResults(allVideos.filter(v => v.title.toLowerCase().includes(q) || v.category.toLowerCase().includes(q)));
  }, [searchQuery]);

  const openVideo = (video) => { setSelectedVideo(video); setIsPlaying(false); setScreen("player"); };

  if (screen === "splash") return <SplashScreen count={splashCount} />;
  if (screen === "player") return (
    <VideoPlayer video={selectedVideo} userEmail={userEmail} watermarkPos={watermarkPos}
      isPlaying={isPlaying} setIsPlaying={setIsPlaying} onBack={() => { setIsPlaying(false); setScreen("home"); }} />
  );

  return (
    <div style={s.app}>
      <div style={s.statusBar}><span style={s.statusTime}>9:41</span><span style={s.statusIcons}>📶 🔋</span></div>

      {/* Header */}
      <div style={s.header}>
        <div style={s.headerLeft}>
          <div style={s.avatarCircle}>{userInitials}</div>
          <div>
            <div style={s.greeting}>Namaste, {userName.split(" ")[0]} 🙏</div>
            <div style={s.greetingSub}>Aapka orchard, aapka gyan</div>
          </div>
        </div>
        {/* Real logo — top right */}
        <div style={s.logoBox}>
          <PHLogo size={36} />
        </div>
      </div>

      {/* Search */}
      <div style={s.searchWrap}>
        <span style={s.searchIcon}>🔍</span>
        <input style={s.searchInput} placeholder="Videos dhundho... (scab, pruning...)" value={searchQuery} onChange={e => setSearchQuery(e.target.value)} />
        {searchQuery && <span style={{ cursor: "pointer", color: "#888", fontSize: 18 }} onClick={() => setSearchQuery("")}>✕</span>}
      </div>

      {searchQuery.length >= 2 ? (
        <div style={s.scrollArea}>
          <div style={s.sectionTitle}>{searchResults.length} results — "{searchQuery}"</div>
          {searchResults.length === 0
            ? <div style={{ textAlign: "center", color: "#888", padding: "40px 20px", fontFamily: "Georgia, serif" }}>Koi video nahi mili 😕<br /><span style={{ fontSize: 13 }}>Doosra keyword try karo</span></div>
            : searchResults.map(v => <SearchResult key={v.id} video={v} onPlay={() => openVideo(v)} />)
          }
        </div>
      ) : (
        <div style={s.scrollArea}>
          <div style={s.sectionTitle}>▶ Continue Watching</div>
          <div style={s.hScroll}>{continueWatching.map(v => <ContinueCard key={v.id} video={v} onPlay={() => openVideo(v)} />)}</div>
          <div style={s.sectionTitle}>🆕 Naya Add Hua</div>
          <div style={s.hScroll}>{allVideos.filter(v => v.new).map(v => <VideoCard key={v.id} video={v} onPlay={() => openVideo(v)} />)}</div>
          {courses.map(cat => (
            <div key={cat.id}>
              <div style={s.sectionTitle}>{cat.icon} {cat.category}</div>
              <div style={s.hScroll}>{cat.videos.map(v => <VideoCard key={v.id} video={{ ...v, categoryColor: cat.color }} onPlay={() => openVideo(v)} />)}</div>
            </div>
          ))}
          <div style={{ height: 80 }} />
        </div>
      )}

      {/* Bottom nav — no Profile tab */}
      <div style={s.bottomNav}>
        {[
          { id: "home", icon: "🏠", label: "Home" },
          { id: "courses", icon: "📚", label: "Courses" },
          { id: "history", icon: "🕐", label: "History" },
        ].map(tab => (
          <div key={tab.id} style={{ ...s.navItem, ...(activeTab === tab.id ? s.navActive : {}) }} onClick={() => setActiveTab(tab.id)}>
            <span style={{ fontSize: 20 }}>{tab.icon}</span>
            <span style={s.navLabel}>{tab.label}</span>
          </div>
        ))}
      </div>
    </div>
  );
}

function SplashScreen({ count }) {
  return (
    <div style={sp.wrap}>
      <div style={sp.bgGlow} />
      {/* Real logo only — no text */}
      <div style={sp.logoWrap}>
        <div style={sp.logoRoseWrap}>
          <PHLogo size={180} />
        </div>
      </div>
      <div style={sp.appName}>Kisan Family Academy</div>
      <div style={sp.tagline}>Apple Farming Knowledge Hub</div>
      {/* Countdown */}
      <div style={sp.countWrap}>
        <div style={sp.countRing}>
          <svg viewBox="0 0 56 56" style={{ position: "absolute", top: 0, left: 0, width: "100%", height: "100%" }}>
            <circle cx="28" cy="28" r="24" fill="none" stroke="#2E7D32" strokeWidth="2" strokeDasharray="150" strokeDashoffset={150 - (count / 3) * 150} strokeLinecap="round" transform="rotate(-90 28 28)" />
          </svg>
          <span style={sp.countNum}>{count}</span>
        </div>
        <div style={sp.countText}>Logging you in...</div>
      </div>
      {/* Footer */}
      <div style={sp.footer}>A product by Priya Haraik Ventures</div>
    </div>
  );
}

function ContinueCard({ video, onPlay }) {
  return (
    <div style={c.continueCard} onClick={onPlay}>
      <div style={c.continuThumb}>{video.thumb}</div>
      <div style={c.continueInfo}>
        <div style={c.continueTitle}>{video.title}</div>
        <div style={c.continueCategory}>{video.category}</div>
        <div style={c.progressBarWrap}><div style={{ ...c.progressBar, width: `${video.progress}%` }} /></div>
        <div style={c.progressText}>{video.progress}% dekha</div>
      </div>
    </div>
  );
}

function VideoCard({ video, onPlay }) {
  return (
    <div style={c.videoCard} onClick={onPlay}>
      <div style={{ ...c.thumb, background: video.categoryColor || "#1B5E20" }}>
        <span style={{ fontSize: 32 }}>{video.thumb}</span>
        {video.new && <div style={c.newBadge}>NEW</div>}
        <div style={c.duration}>{video.duration}</div>
      </div>
      <div style={c.videoTitle}>{video.title}</div>
      <div style={c.videoViews}>{video.views?.toLocaleString()} views</div>
    </div>
  );
}

function SearchResult({ video, onPlay }) {
  return (
    <div style={sr.row} onClick={onPlay}>
      <div style={{ ...sr.thumb, background: video.categoryColor || "#1B5E20" }}><span style={{ fontSize: 24 }}>{video.thumb}</span></div>
      <div style={sr.info}>
        <div style={sr.title}>{video.title}</div>
        <div style={sr.meta}>{video.category} • {video.duration}</div>
      </div>
      <div style={sr.play}>▶</div>
    </div>
  );
}

function VideoPlayer({ video, userEmail, watermarkPos, isPlaying, setIsPlaying, onBack }) {
  const [progress, setProgress] = useState(35);
  useEffect(() => {
    if (!isPlaying) return;
    const interval = setInterval(() => setProgress(p => Math.min(p + 0.5, 100)), 500);
    return () => clearInterval(interval);
  }, [isPlaying]);

  return (
    <div style={p.wrap}>
      <div style={p.videoArea}>
        <div style={p.videoBg}>
          {!isPlaying ? (
            <div style={p.playBtnWrap}>
              <div style={p.thumbEmoji}>{video?.thumb || "🎬"}</div>
              <div style={p.playBtn} onClick={() => setIsPlaying(true)}>▶</div>
              <div style={p.videoTitleOverlay}>{video?.title}</div>
            </div>
          ) : (
            <div style={p.playingState}>
              <div style={p.playingEmoji}>{video?.thumb || "🎬"}</div>
              <div style={p.playingLabel}>▶ Playing...</div>
              <div style={p.pauseBtn} onClick={() => setIsPlaying(false)}>⏸</div>
            </div>
          )}
          <div style={{ ...p.watermark, top: watermarkPos.top, left: watermarkPos.left }}>{userEmail}</div>
        </div>
        <div style={p.progressWrap}><div style={{ ...p.progressFill, width: `${progress}%` }} /></div>
      </div>
      <div style={p.info}>
        <div style={p.backBtn} onClick={onBack}>← Back</div>
        <div style={p.videoTitle}>{video?.title}</div>
        <div style={p.videoMeta}>{video?.duration} • {video?.category || "Apple Farming"}</div>
        <div style={p.divider} />
        <div style={p.sectionHead}>Up Next</div>
        {[{ title: "Alternaria Leaf Blight", duration: "19:08", thumb: "🌿" }, { title: "Powdery Mildew Treatment", duration: "16:55", thumb: "🧪" }].map((v, i) => (
          <div key={i} style={p.nextRow}>
            <div style={p.nextThumb}>{v.thumb}</div>
            <div><div style={p.nextTitle}>{v.title}</div><div style={p.nextDuration}>{v.duration}</div></div>
          </div>
        ))}
      </div>
    </div>
  );
}

